# Portable vector pack example
"""A query embedding generated by the recorded recipe travels with the example.
No model or network is needed to validate the exported vectors. To ask a new
query embed it with the manifest's GGUF model hash, tokenizer, CLS pooling,
query prefix and L2 normalization, using the recorded llama.cpp commit.
"""
import hashlib
import json
from pathlib import Path
import sys
import subprocess
import numpy as np
import pyarrow.parquet as pq

pack = Path(sys.argv[1])
manifest = json.loads((pack / 'manifest.json').read_text())
for name, digest in manifest['files'].items():
    assert hashlib.sha256((pack / name).read_bytes()).hexdigest() == digest, name
example = json.loads((pack / 'examples/query.json').read_text())
recipe = json.dumps(manifest['embedding_recipe'], sort_keys=True, ensure_ascii=False, separators=(',', ':'))
assert hashlib.sha256(recipe.encode()).hexdigest() == example['embedding_recipe_sha256']
# JSON key order differs by language; compare the actual recipe fields explicitly.
assert manifest['embedding_recipe']['normalization'] == 'l2'
assert manifest['embedding_recipe']['pooling'] == 'cls'
chunks = pq.read_table(pack / 'chunks.parquet').to_pylist()
docs = {d['doc_id']: d for d in pq.read_table(pack / 'documents.parquet').to_pylist()}
query = np.asarray(example['query_embedding'], dtype=np.float32)
if len(sys.argv) > 2:
    # Recompute from the exact recorded GGUF recipe with the same linked engine.
    result = json.loads(subprocess.check_output([sys.argv[2], '--cpu', 'embed', example['query']], text=True, encoding="utf-8"))
    assert result['recipe'] == manifest['embedding_recipe']
    recomputed = np.asarray(result['embedding'], dtype=np.float32)
    np.testing.assert_allclose(query, recomputed, rtol=1e-4, atol=1e-5)
    query = recomputed
assert query.shape == (manifest['embedding_recipe']['dimensions'],)
scores = [(c['chunk_id'], float(np.dot(np.asarray(c['embedding'], dtype=np.float32), query))) for c in chunks]
scores.sort(key=lambda item: (-item[1], item[0]))
actual = [item[0] for item in scores[:3]]
assert actual == example['expected_top'], (actual, example['expected_top'])
for chunk in chunks:
    assert chunk['doc_id'] in docs
    assert 1 <= chunk['page'] <= docs[chunk['doc_id']]['pages']
print(json.dumps({'query': example['query'], 'top': actual, 'hashes': 'OK', 'citations': 'OK'}))
